package com.codepilot1c.core.edt.compare;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.time.Instant;import com.google.gson.*;
/** Local immutable plan evidence. No project paths supplied by the caller, no automatic source application. */
public final class MergeCheckpointStore {
 private static final Gson JSON=new GsonBuilder().serializeNulls().create();private final Path root;
 public MergeCheckpointStore(Path root)throws Exception{this.root=root;Files.createDirectories(root);}
 private Path path(String id){if(id==null||!id.matches("merge-[a-f0-9-]{36}"))throw new IllegalArgumentException("Invalid checkpoint_id");return root.resolve(id+".json");}
 public Map<String,Object> save(Map<String,Object> plan)throws Exception{var doc=new LinkedHashMap<>(plan);String id="merge-"+UUID.randomUUID();doc.put("checkpoint_id",id);doc.put("created_at",Instant.now().toString());String text=JSON.toJson(doc);if(text.getBytes(StandardCharsets.UTF_8).length>16*1024*1024)throw new IllegalArgumentException("Checkpoint exceeds 16 MiB; narrow scope");Files.writeString(path(id),text,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);return summary(doc,text);}
 @SuppressWarnings("unchecked") public Map<String,Object> load(String id,String expected)throws Exception{Path p=path(id);if(Files.isSymbolicLink(p)||Files.size(p)>16*1024*1024)throw new IllegalStateException("Invalid checkpoint file");String text=Files.readString(p,StandardCharsets.UTF_8);if(expected!=null)EdtComparisonService.requireHash(expected,EdtComparisonService.hash(text));var doc=JSON.fromJson(text,LinkedHashMap.class);if(!id.equals(doc.get("checkpoint_id")))throw new IllegalStateException("Checkpoint identity mismatch");return doc;}
 public Map<String,Object> read(String id)throws Exception{var doc=load(id,null);return summary(doc,Files.readString(path(id),StandardCharsets.UTF_8));}
 private static Map<String,Object> summary(Map<String,Object>d,String text){var out=new LinkedHashMap<String,Object>();for(String key:List.of("checkpoint_id","created_at","main_project","other_project","ancestor_project","node_count","source_guard"))out.put(key,d.get(key));out.put("checkpoint_sha256",EdtComparisonService.hash(text));out.put("source_projects_changed",false);return out;}
 public static String nodeKey(Map<String,Object> row){if(Boolean.TRUE.equals(row.get("order_set_by_user")))throw new IllegalArgumentException("Explicit subordinate order is not yet supported by checkpoints; keep the comparison open");boolean resolved=Boolean.TRUE.equals(row.get("path_resolved"));boolean namedElement="TopMdObjectCollectionElementComparisonNode".equals(row.get("kind"))&&(row.get("main_fqn") instanceof String||row.get("other_fqn") instanceof String);if(!resolved&&!namedElement)throw new IllegalArgumentException("Unresolved technical node cannot be persisted safely");var fields=new TreeMap<String,Object>();for(String key:List.of("path","kind","main_fqn","other_fqn","main_name","other_name","section_type","checkpoint_parent_key"))if(row.containsKey(key)&&(!key.equals("path")||resolved))fields.put(key,row.get(key));return EdtComparisonService.hash(JSON.toJson(fields));}
 public static Map<String,Map<String,Object>> index(List<Map<String,Object>> rows){var byId=new HashMap<String,Map<String,Object>>();for(var row:rows)if(byId.put((String)row.get("node_id"),row)!=null)throw new IllegalStateException("Duplicate comparison node");var index=new LinkedHashMap<String,Map<String,Object>>();var keys=new HashMap<String,String>();for(var row:rows){String key=qualified(row,byId,keys,new HashSet<>());if(index.put(key,row)!=null)throw new IllegalStateException("Ambiguous semantic node identity; narrow comparison scope");}return index;}
 private static String qualified(Map<String,Object> row,Map<String,Map<String,Object>> rows,Map<String,String> keys,Set<String> visiting){String id=(String)row.get("node_id");if(keys.containsKey(id))return keys.get(id);if(!visiting.add(id))throw new IllegalStateException("Cyclic comparison tree");Object parent=row.get("parent_id");if(parent!=null){var owner=rows.get(parent);if(owner==null)throw new IllegalStateException("Comparison parent unavailable");row.put("checkpoint_parent_key",qualified(owner,rows,keys,visiting));}String key=nodeKey(row);keys.put(id,key);visiting.remove(id);return key;}
}
